const API_BASE_URL = (() => {
  const params = new URLSearchParams(location.search);
  let stored = null;
  try { stored = localStorage.getItem('FINN_API_BASE_URL'); } catch {}
  const configured = window.FINN_CONFIG?.apiBaseUrl || params.get('apiBase') || stored;
  const raw = configured || (['http:', 'https:'].includes(location.protocol) ? location.origin : '');
  return raw ? raw.replace(/\/$/, '') : '';
})();

async function apiGet(path, options = {}) {
  if (!API_BASE_URL) throw new Error('FINN API origin is not configured.');
  let response;
  try {
    response = await fetch(`${API_BASE_URL}${path}`, {
      ...options,
      headers: { Accept: 'application/json', ...(options.headers || {}) },
    });
  } catch (error) {
    throw new Error(`Could not reach FINN API at ${API_BASE_URL}: ${error.message || 'network error'}`);
  }
  const contentType = response.headers.get('content-type') || '';
  const payload = contentType.includes('application/json') ? await response.json() : await response.text();
  if (!response.ok) {
    const detail = typeof payload === 'object' && payload ? payload.detail : payload;
    const message = typeof detail === 'string' ? detail : detail?.message || detail?.code || response.statusText;
    throw new Error(`${response.status}: ${message || 'API request failed'}`);
  }
  return payload;
}

