function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
function safeUrl(value){try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:null}catch{return null}}
function showResearchSection(section='overview'){const allowed=['overview','financials','commitments','documents'];const active=allowed.includes(section)?section:'overview';document.querySelectorAll('.company-tabs button').forEach(button=>{const selected=(button.dataset.tab||'overview')===active;button.classList.toggle('selected',selected);button.setAttribute('aria-selected',String(selected))});const commitments=active==='commitments',documents=active==='documents';document.getElementById('commitmentsView').hidden=!commitments;document.getElementById('documentsView').hidden=!documents;document.querySelector('.research-grid').hidden=commitments||documents;document.querySelectorAll('[data-research-tab]').forEach(node=>node.hidden=!node.dataset.researchTab.split(/\s+/).includes(active));document.querySelector('.research-grid').classList.toggle('financials-mode',active==='financials');document.querySelector('.research-grid').classList.toggle('overview-mode',active==='overview');if(location.hash==='#commitments'||location.hash==='#documents'||location.hash==='#financials')history.replaceState(null,'',`#${active}`)}
