async function loadResearchCoverage(ticker){const panel=document.getElementById('coveragePanel');panel.innerHTML='<span>Loading company coverage…</span>';try{const data=await apiGet(`/api/research-coverage/${encodeURIComponent(ticker)}`);if(dataMode!=='live'||selectedCompany?.ticker!==ticker)return;researchCoverage=data;const labels={eod_market_data:'EOD market data',exchange_announcements:'NSE announcements',official_business_profile:'Business profile',provider_financial_statements:'Provider financial statements',annual_reports:'Annual reports',quarterly_results:'Financial results',earnings_call_transcripts:'Concall transcripts',indexed_document_pages:'Indexed pages',validated_financial_observations:'Validated financial observations',management_statements_and_commitments:'Management statements'};panel.innerHTML=Object.entries(data.states).map(([key,state])=>`<div class="coverage-row"><span>${escapeHtml(labels[key]||key)}</span><b data-state="${escapeHtml(state)}">${escapeHtml(state.replaceAll('_',' '))}</b></div>`).join('');const report=data.states.annual_reports;document.getElementById('sourceCoverageTitle').textContent=report==='available'?`${data.company} · research sources available`:report==='not_connected'?`${data.company} · limited research coverage`:`${data.company} · ${report.replaceAll('_',' ')}`;document.getElementById('sourceCoverageText').textContent=report==='not_connected'?'No original annual report is connected. Provider-sourced financial statements may still be available and are shown separately from filing-validated data.':report==='indexed_not_extracted'?'The report is indexed, but financial extraction has not been performed.':report==='needs_review'?'Financial extraction exists and awaits source validation.':report==='provider_error'?'The official source provider returned an error; this is not an empty-data result.':'Statuses below come from stored sources and extraction records.'}catch(e){if(dataMode!=='live'||selectedCompany?.ticker!==ticker)return;panel.innerHTML=`<span class="coverage-error">Coverage API failure: ${escapeHtml(e.message)}</span>`;document.getElementById('sourceCoverageTitle').textContent='Coverage service unavailable';document.getElementById('sourceCoverageText').textContent='Unable to determine source coverage because the backend request failed.'}}
